targets.expr:
sum(
  increase(
    argo_workflows_count_total{

      phase="Succeeded"
    }[6h]
  )
)
/
sum(
  increase(
    argo_workflows_count_total{
      phase=~'Succeeded|Failed|Error'
    }[6h]
  )
)
* 100

sum(
  increase(
    argo_workflows_count_total{

      phase='Succeeded'
    }[$__rate_interval]
  )
)
/
sum(
  increase(
    argo_workflows_count_total{


      phase=~'Succeeded|Failed|Error'
    }[$__rate_interval]
  )
)
* 100

topk(
  10,
  sum by(exported_namespace)(
    increase(
      argo_workflows_count_total{
        phase=~"Succeeded|Failed|Error"
      }[6h]
    )
  )
)

topk(
  10,
  sum by(exported_namespace)(
    increase(
      argo_workflows_count_total{
        phase=~"Failed|Error"
      }[6h]
    )
  )
)
